insert into public.accessories (
  id, name, description, price_lithons, asset_path, slot, active, sort_order,
  preview_path, triangle_count, dimensions, scale_min, scale_max, physics, collision, budget
)
select
  id, name, description, price_lithons, asset_path, slot, false, sort_order,
  preview_path, triangle_count, dimensions, scale_min, scale_max, physics, collision, budget
from staged
on conflict (id) do update set
  name = excluded.name,
  description = excluded.description,
  price_lithons = excluded.price_lithons,
  asset_path = excluded.asset_path,
  slot = excluded.slot,
  active = false,
  sort_order = excluded.sort_order,
  preview_path = excluded.preview_path,
  triangle_count = excluded.triangle_count,
  dimensions = excluded.dimensions,
  scale_min = excluded.scale_min,
  scale_max = excluded.scale_max,
  physics = excluded.physics,
  collision = excluded.collision,
  budget = excluded.budget;

commit;
